'use strict';

function _attach(context, options) {

	var $ = context.jQuery;

	//Data object to set as attribute
	var data = {};

	//Process every option of the validation object
	$.each(options, function(key, value) {

		//Create the rules data
		if (key === 'rules') {

			$.each(value, function(rule, condition) {

				data['data-rule-' + rule] = condition;

			});

		}

		//Create the messages data
		if (key === 'messages') {

			$.each(value, function(message, text) {

				data['data-msg-' + message] = text;

			});

		}

	});

	//Set the attributes for the validation
	this.find(':input:not(:button)').attr(data);

}

module.exports = {
	attach: _attach
};
